        cin >> s;
    	dis[s] = 0;
    	for (int i = 1; i <= n; i++) {
    		int minn = inf, minx = -1;
    		for (int j = 1; j <= n; j++) {
    			if (__________) { // 在此处填入选项
    				minn = dis[j];
    				minx = j;
    			}
